const tabId = 1148881640;
const bundleInfo = await browserjs(tabId, async () => {
  // Check main-primary.js and main-secondary.js or rollup.min.js
  const scriptTags = Array.from(document.querySelectorAll('script[src*="bundle"]'));
  const urls = scriptTags.map(s => s.src);
  const found = [];
  for (const u of urls) {
    try {
      const res = await fetch(u);
      const text = await res.text();
      if (text.includes('autocomplete') || text.includes('searchterm') || text.includes('livesearch')) {
        found.push({ url: u, match: true, len: text.length });
        // find occurrences of endpoint / url in the text
        const matches = text.match(/\/api\/[a-zA-Z0-9_\/.-]+|\/search[a-zA-Z0-9_\/.-]*|\/livesearch[a-zA-Z0-9_\/.-]*/g);
        found.push({ url: u, endpoints: matches ? [...new Set(matches)] : [] });
      }
    } catch(e) {
      found.push({ url: u, error: e.message });
    }
  }
  return found;
});
console.log(JSON.stringify(bundleInfo, null, 2));

